import json
p=json.load(open('/work/report-passages.json')); by={x['id']:x for x in p};items=[]
def ids(*values):
 r=[]
 for v in values:
  if isinstance(v,int):r.append(v)
  else:r.extend(range(v[0],v[1]+1))
 return [f'P{i:04}' for i in sorted(set(r))]
def add(title,loc,s,status,sev,note,noise=None):
 sources=ids(*s)
 items.append(dict(item=title,loc=loc,sources=sources,reports=''.join(sorted({by[i]['report'] for i in sources})),status=status,severity=sev,noise_class=noise,note=note))
